150		@ResponseBody
151		public ResultDTO<Void> refreshEvalOrder(@RequestBody List<String> orderNos) {
152			// 旧全国货单考核
153			ResultDTO<Void> resultDTO = new ResultDTO<>();
154	
155			for (String orderNo : orderNos) {
156				FigureParam figureParam = indicatorDAGService.transEventNodeByOrder(orderNo, null, null, 0);
157				if (figureParam == null) {
158					// 创建indicator_order数据
159					IndicatorOrderBO indicatorOrderBO = new IndicatorOrderBO();
160					indicatorOrderServiceImpl.buildOrderBaseInfo(orderNo, indicatorOrderBO);
161					indicatorOrderBO.setCurrentNode("");
162					indicatorOrderBO.setCurrentNodeCode(0);
163					IndicatorOrder order = indicatorOrderServiceImpl.toOrder(indicatorOrderBO);
164					indicatorOrderDao.save(order);
165					figureParam = indicatorDAGService.transEventNodeByOrder(orderNo, null, null, 0);
166					if (figureParam == null) {
167						LOGGER.info("refreshEvalOrder, 订单{}未找到考核载体信息，跳过考核计算", orderNo);
168						continue;
169					}
170				}
171				LOGGER.info("refreshEvalOrder处理货单{}", orderNo);
172				evalOrderService.calculateIndicatorByEvents(figureParam.getProjectOrderNo(), figureParam.getStartNodes(), figureParam.getExtNodes());
173			}
174			resultDTO.success();
175			return resultDTO;
