363		@PostMapping("/api/refresh/eval/order/latestVersion")
364		@ResponseBody
365		public ResultDTO<Void> refreshEvalOrderWithLatestVersion(@RequestBody List<RefreshOrderVersionParam> param) {
366			// 旧全国货单考核
367			// 支持使用最新的考核规则重算
368			ResultDTO<Void> resultDTO = new ResultDTO<>();
369	
370			for (RefreshOrderVersionParam p : param) {
371				try {
372					// 如果是材料进排程的任务, 不处理
373					FulfillmentTaskExample taskExample = new FulfillmentTaskExample();
374					taskExample.createCriteria()
375							.andRelateSubOrderNoEqualTo(p.getOrderNo())
376							.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode())
377							.andIsDeleteEqualTo((byte) 0);
378					FulfillmentTask task = fulfillmentTaskMapper.selectOneByExample(taskExample);
379					if (task == null) {
380						continue;
381					}
382					if (edarStarlordRpc.queryProjectInScheduleSwitch(task.getProjectCode())) {
383						continue;
384					}
385					if (p.getNewVersion()) {
386						// 删除现有考核结果, 即强制使用最新版本的考核规则计算
387						IndicatorOrderExample orderExample = new IndicatorOrderExample();
388						orderExample.createCriteria()
389								.andOrderNoEqualTo(p.getOrderNo())
390								.andIsDeleteEqualTo((byte) 0);
391						IndicatorOrder order = indicatorOrderMapper.selectOneByExample(orderExample);
392						order.setBaseEvalResultNew("[]");
393						order.setCusEvalResultNew("[]");
394						indicatorOrderMapper.updateByPrimaryKeySelective(order);
395					}
396					FigureParam figureParam = indicatorDAGService.transEventNodeByOrder(p.getOrderNo(), null, null, 0);
397					evalOrderService.calculateIndicatorByEvents(figureParam.getProjectOrderNo(), figureParam.getStartNodes(), figureParam.getExtNodes());
398					LOGGER.info("refreshEvalOrderWithLatestVersion货单: {}执行成功", p.getOrderNo());
399				} catch (Exception e) {
400					LOGGER.info("refreshEvalOrderWithLatestVersion货单: {}执行失败, e:", p.getOrderNo(), e);
401				}
402			}
403			resultDTO.success();
404			return resultDTO;
405		}
