420		@PostMapping("/api/test/schedule/createAndActiveDeliveryTask")
421		@ResponseBody
422		public ResultDTO<Void> createAndActiveDeliveryTask(@RequestParam("orderNo") String orderNo) {
423			ResultDTO<Void> resultDTO = new ResultDTO<>();
424			FulfillmentTaskExample example = new FulfillmentTaskExample();
425			example.createCriteria()
426					.andRelateSubOrderNoEqualTo(orderNo)
427					.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode())
428					.andStatusEqualTo(FulfillmentTaskStatusEnum.GENERATED.getTypeCode())
429					.andIsDeleteEqualTo((byte) 0);
430			FulfillmentTask task = fulfillmentTaskMapper.selectOneByExample(example);
431			if (task != null) {
432				// 通知送货已存在, 直接返回
433				return resultDTO;
434			}
435	
436			// 查询货单信息, 只处理材料进排程的货单
437			SubOrderComplexDto subOrderComplexDto;
438			try {
439				subOrderComplexDto = omsRpc.queryBaseByOrderNo(orderNo);
440				if (!edarStarlordRpc.queryProjectInScheduleSwitch(subOrderComplexDto.getProjectOrderId().toString())) {
441					// 排程开关未打开, 直接返回
442					return resultDTO;
443				}
444			} catch (Exception e) {
445				LOGGER.error("查询oms异常, queryBaseByOrderNo orderNo:{}, err:", orderNo, e);
446				return resultDTO;
447			}
448	
449			fulfillmentTaskWriteService.initTask(ScheduleInitParam.builder().orderNo(orderNo).build());
450			task = fulfillmentTaskMapper.selectOneByExample(example);
451			if (task != null) {
452				// 通知送货已存在, 尝试激活
453				LOGGER.info("创建任务成功, orderNo:{}, 尝试激活", orderNo);
454				notifyDeliveryTaskBizService.tryActiveNoticeDeliveryTask(task);
455			}
456			resultDTO.success();
457			return resultDTO;
458		}
