30	
31	@RestController
32	@Slf4j
33	public class BizQueryIndicatorOrderController implements BizQueryIndicatorOrderApi {
34	
35		@Resource
36		private OfcRpc ofcRpc;
37	
38		@Resource
39		private IndicatorOrderDao indicatorOrderDao;
40	
41		@Resource
42		private SubOrderQueryManager subOrderQueryManager;
