44		@Resource
45		private IndicatorOrderService indicatorOrderService;
46	
47	
48		@Override
49		public ResultDTO<OrderTimeDto> queryOrderTime(BizQueryIndicatorOrderParam param) {
50			LOGGER.info("queryOrderTime param:{}", JsonUtil.obj2JsonStr(param));
51			ResultDTO<OrderTimeDto> resultDTO = new ResultDTO<>();
52			OrderTimeDto orderTimeDto = new OrderTimeDto();
53			orderTimeDto.setProjectOrderId(param.getProjectOrderId());
54	
55			List<IndicatorOrder> indicatorOrders = indicatorOrderDao.queryByProjectOrderIdAndCategoryIdAndSupplierId(param.getProjectOrderId(), param.getCategoryId(), param.getSupplierId(), param.getOrderNos());
56			if (CollectionUtils.isEmpty(indicatorOrders)) {
57				orderTimeDto.setOrderFlowNodeTimes(Lists.newArrayList());
58				resultDTO.success(orderTimeDto);
59				return resultDTO;
60			}
61			List<OrderTimeDto.OrderFlowNodeTime> orderFlowNodeTimes = new ArrayList<>();
62			indicatorOrders.forEach(order -> {
63				try {
64					OrderTimeDto.OrderFlowNodeTime orderFlowNodeTime = new OrderTimeDto.OrderFlowNodeTime();
65					List<OrderTimeDto.NodeTime> nodeTimes = Lists.newArrayList();
66					List<DispatchReceiveDto> dispatchReceiveDtos = ofcRpc.queryDispatchReceiveByMainFlowNo(order.getOrderNo());
67					SubOrderComplexDto subOrderComplexDto = subOrderQueryManager.querySubOrderBaseInfo(order.getOrderNo());
68					// 实际完成时间
69					Map<Integer, List<DispatchReceiveDto>> dispatchMap = Optional.ofNullable(dispatchReceiveDtos).orElse(new ArrayList<>()).stream()
70							.filter(d -> d.getOperationTime().compareTo(DateUtil.parse("2000-01-01",DateUtil.DATE_FMT_3)) > 0)
71							.collect(Collectors.groupingBy(DispatchReceiveDto::getActionType));
72					// 期望完成时间
73					Map<String, Long> expectTime = this.getExpectTime(param.getNodeIds(), order);
74					param.getNodeIds().forEach(w -> {
75						OrderTimeDto.NodeTime nodeTime = new OrderTimeDto.NodeTime();
76						nodeTime.setNodeId(w);
77						nodeTime.setCompleteTimes(dispatchMap.getOrDefault(Integer.valueOf(w), new ArrayList<>()).stream().map(o -> o.getOperationTime().getTime()).collect(Collectors.toList()));
78						nodeTime.setPlanCompleteTime(expectTime.getOrDefault(w, 0L));
79						nodeTimes.add(nodeTime);
80					});
81					orderFlowNodeTime.setPlanArrivedTime(subOrderComplexDto.getPlanArrivedTime() != null ? subOrderComplexDto.getPlanArrivedTime().getTime() : 0L);
82					orderFlowNodeTime.setOrderNo(order.getOrderNo());
83					orderFlowNodeTime.setNodeTimes(nodeTimes);
84					orderFlowNodeTimes.add(orderFlowNodeTime);
85				} catch (RpcException e) {
86					throw new RuntimeException(e);
87				}
88			});
89			orderTimeDto.setOrderFlowNodeTimes(orderFlowNodeTimes);
90			resultDTO.success(orderTimeDto);
91			return resultDTO;
92		}
93	
94		public Map<String,Long> getExpectTime(List<String> nodeIds, IndicatorOrder order) {
95			Map<String,Long> expectTimeMap = new HashMap<>();
96			List<IndicatorEvalSDO> baseList = JsonUtil.jsonStr2Obj(order.getBaseEvalResultNew(), new TypeReference<List<IndicatorEvalSDO>>() {});
97			List<IndicatorEvalSDO> cusList = JsonUtil.jsonStr2Obj(order.getCusEvalResultNew(), new TypeReference<List<IndicatorEvalSDO>>() {});
98			Map<String, IndicatorEvalSDO> indicatorEvalSDOMap = baseList.stream().collect(Collectors.toMap(IndicatorEvalSDO::getEndNode, a -> a));
99			Map<String, IndicatorEvalSDO> cusEvalSDOMap = cusList.stream().collect(Collectors.toMap(IndicatorEvalSDO::getEndNode, a -> a));
100	
101			for (String nodeId : nodeIds) {
102				IndicatorEvalSDO indicatorEvalSDO = indicatorEvalSDOMap.get(nodeId);
103				IndicatorEvalSDO cusEvalSDO = cusEvalSDOMap.get(nodeId);
104				if (cusEvalSDO != null && StringUtils.isNotBlank(cusEvalSDO.getExpectCompTime())) {
105					expectTimeMap.put(nodeId, DateUtil.parse(cusEvalSDO.getExpectCompTime(), DateUtil.DATE_FMT_2).getTime());
106				} else if(indicatorEvalSDO != null && StringUtils.isNotBlank(indicatorEvalSDO.getExpectCompTime())) {
107					expectTimeMap.put(nodeId, DateUtil.parse(indicatorEvalSDO.getExpectCompTime(), DateUtil.DATE_FMT_2).getTime());
108				} else {
109					expectTimeMap.put(nodeId, 0L);
110				}
111			}
112			return expectTimeMap;
113		}
