88		private String getGranularityDesc(NIndicatorCusConfig indicatorCusConfig) {
89			StringBuilder granularityDesc = new StringBuilder();
90			if (indicatorCusConfig.getGranularityType().equals(GranularityTypeEnum.LEVEL_2.getType())) {
91				granularityDesc.append(indicatorCusConfig.getQvyu());
92			}
93			if (indicatorCusConfig.getGranularityType().equals(GranularityTypeEnum.LEVEL_3.getType())) {
94				granularityDesc.append(indicatorCusConfig.getQvyu()).append(" ").append(indicatorCusConfig.getBranchName());
95			}
96			if (indicatorCusConfig.getGranularityType().equals(GranularityTypeEnum.LEVEL_4.getType())) {
97				granularityDesc
98					.append(indicatorCusConfig.getQvyu()).append(" ")
99					.append(indicatorCusConfig.getBranchName()).append(" ")
100					.append(indicatorCusConfig.getMerchantName()).append(" ")
101					.append(indicatorCusConfig.getDeliveryName());
102			}
103			return granularityDesc.toString();
104		}
