164		private static List<SubDataPageView> getSubDataPageViews(Integer viewType,List<IndicatorComputeRule> indicatorComputeRules) {
165			if (CollectionUtils.isEmpty(indicatorComputeRules)) {
166				return Lists.newArrayList();
167			}
168			return indicatorComputeRules.stream().map(rule -> {
169				SubDataPageView subView = new SubDataPageView();
170				subView.setId(rule.getId());
171				if (viewType.equals(1)) {
172					subView.setDimName(rule.getCategoryName());
173					subView.setCategoryId(rule.getCategoryId());
174				} else {
175					subView.setDimName(rule.getIndicatorName());
176				}
177				subView.setDeliveryTypeDesc(DeliveryTypeEnum.getDescByType(rule.getDeliveryType().byteValue()));
178				if (rule.getHasMeasurementNode().equals(1)) {
179					subView.setHasMeasurementNodeDesc("是");
180				} else if (rule.getHasMeasurementNode().equals(0)) {
181					subView.setHasMeasurementNodeDesc("否");
182				} else {
183					subView.setHasMeasurementNodeDesc("-");
184				}
185				if (rule.getHasDeliveryNotificationNode().equals(1)) {
186					subView.setHasDeliveryNotificationNodeDesc("是");
187				} else if (rule.getHasDeliveryNotificationNode().equals(0)) {
188					subView.setHasDeliveryNotificationNodeDesc("否");
189				} else {
190					subView.setHasDeliveryNotificationNodeDesc("-");
191				}
192				if (StringUtils.isNotEmpty(rule.getBaseComputeRuleNew()) && rule.getSourceType().equals(0)) {
193					CategoryComputeRule.FuncTimeRule funcTimeRule = JsonUtil.jsonStr2Obj(rule.getBaseComputeRuleNew(), CategoryComputeRule.FuncTimeRule.class);
194					subView.setBaseComputeRule(funcTimeRule.getHumanDesc());
195				}
196				if (StringUtils.isNotEmpty(rule.getCusComputeRuleNew()) && rule.getSourceType().equals(1)) {
197					CategoryComputeRule.FuncTimeRule funcTimeRule = JsonUtil.jsonStr2Obj(rule.getCusComputeRuleNew(), CategoryComputeRule.FuncTimeRule.class);
198					subView.setBaseComputeRule(funcTimeRule.getHumanDesc());
199				}
200				subView.setMtime(DateUtil.formatTime(rule.getMtime()));
201				subView.setStartTime(DateUtil.date2String(rule.getStartTime()));
202				subView.setEndTime(DateUtil.date2String(rule.getEndTime()));
203				subView.setDeliveryInfoList(JsonUtil.jsonStr2Obj(rule.getDeliveryInfo(), new TypeReference<List<DeliveryInfo>>() {}));
204				return subView;
205			}).collect(Collectors.toList());
206		}
