391			ResultDTO<List<IndicatorCategoryComputeRuleView>> resultDTO = new ResultDTO<>();
392	
393			// 合并城市自定义和底线的规则
394			List<IndicatorComputeRule> allRules = Lists.newArrayList();
395	
396			NIndicatorCusConfig indicatorCusConfig = nIndicatorCusConfigMapper.selectByPrimaryKey(id);
397			NIndicatorBaseConfigExample configExample = new NIndicatorBaseConfigExample();
398			configExample.createCriteria()
399					.andIndicatorNameEqualTo(indicatorCusConfig.getIndicatorName())
400					.andSecondTypeEqualTo(indicatorCusConfig.getSecondType())
401					.andBusinessTypeEqualTo(indicatorCusConfig.getBusinessType())
402					.andBusinessVersionEqualTo(indicatorCusConfig.getBusinessVersion())
403					.andIsDeleteEqualTo((byte)  0);
404			NIndicatorBaseConfig baseConfig = nIndicatorBaseConfigMapper.selectOneByExample(configExample);
405	
406			List<IndicatorComputeRule> baseComputeRules;
407			if (baseConfig != null) {
408				baseComputeRules = bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(baseConfig.getId(), 0, null, null);
409			} else {
410				baseComputeRules = new ArrayList<>();
411			}
412	
413			// 查询城市关联的底线指标
414			List<IndicatorComputeRule> cusComputeRules = bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(id, 1, null, null);
415			cusComputeRules.forEach(cusRule -> {
416				baseComputeRules.stream()
417						.filter(d -> getDimKey(cusRule).equals(getDimKey(d)))
418						.findFirst().ifPresent(d -> {
419							cusRule.setBaseComputeRuleNew(d.getBaseComputeRuleNew());
420				});
421			});
422			allRules.addAll(cusComputeRules);
423	
424			// 合并城市中没有底线规则
425			for (IndicatorComputeRule baseRule : baseComputeRules) {
426				if (allRules.stream().noneMatch(d -> getDimKey(baseRule).equals(getDimKey(d)))) {
427					allRules.add(baseRule);
428				}
429			}
430			List<IndicatorCategoryComputeRuleView> indicatorCategoryComputeRuleViews =
431				allRules.stream().map(IndicatorComputeRuleTransformer::toIndicatorCategoryComputeRuleView)
432						.sorted(Comparator.comparing((IndicatorCategoryComputeRuleView v) -> v.getCategoryInfoList().get(0).getCategoryId())
433							.thenComparing(IndicatorCategoryComputeRuleView::getDeliveryTypeDesc)
434							.thenComparing(IndicatorCategoryComputeRuleView::getHasMeasurementNodeDesc)
435							.thenComparing(IndicatorCategoryComputeRuleView::getHasDeliveryNotificationNodeDesc)).collect(Collectors.toList());
436			resultDTO.success(indicatorCategoryComputeRuleViews);
437			return resultDTO;
438		}
