469		@Override
470		public ResultDTO<List<CategoryComputeRule>> queryIndicatorComputeRule(Long id, String categoryId, Integer sourceType, Long sourceId) {
471			ResultDTO<List<CategoryComputeRule>> resultDTO = new ResultDTO<>();
472			List<IndicatorComputeRule> indicatorComputeRules;
473	
474			// 用于后续北京的特殊处理
475			boolean isBeijing = false;
476			NIndicatorCusConfig indicatorCusConfig = null;
477			if (sourceType.equals(1)) {
478				// 查询底线的sourceId, 然后查询底线计算规则
479				indicatorCusConfig = nIndicatorCusConfigMapper.selectByPrimaryKey(sourceId);
480				isBeijing = "北京".equals(indicatorCusConfig.getQvyu());
481			}
482	
483	
484			//  查询当前sourceId的指标配置, 可能是底线, 也可能是一城一策, 取决于sourceType
485			String deliveryInfo = null;
486			if (isBeijing) {
487				// 北京的deliveryInfo需要单独查询
488				IndicatorComputeRule beijingRule = indicatorComputeRuleMapper.selectByPrimaryKey(id);
489				if (beijingRule != null) {
490					deliveryInfo = beijingRule.getDeliveryInfo();
491				}
492			}
493			indicatorComputeRules = bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(sourceId, sourceType, categoryId, deliveryInfo);
494	
495			if (sourceType.equals(1) && indicatorCusConfig != null) {
496				// 查询的是一城一策规则
497				// 所以需要先查询一城一策指标下的品类规则(可能查不到, 或不完整例如delivery_type, has_measurement_node, has_delivery_notification_node)
498				// 然后再合并底线规则
499	
500				NIndicatorBaseConfigExample baseExample = new NIndicatorBaseConfigExample();
501				baseExample.createCriteria()
502						.andIndicatorNameEqualTo(indicatorCusConfig.getIndicatorName())
503						.andSecondTypeEqualTo(indicatorCusConfig.getSecondType())
504						.andBusinessVersionEqualTo(indicatorCusConfig.getBusinessVersion())
505						.andBusinessTypeEqualTo(indicatorCusConfig.getBusinessType())
506						.andIsDeleteEqualTo((byte) 0);
507				NIndicatorBaseConfig baseConfig = nIndicatorBaseConfigMapper.selectOneByExample(baseExample);
508				if (baseConfig != null) {
509					List<IndicatorComputeRule> baseRules = bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(baseConfig.getId(), 0, categoryId, null);
510	
511					// 北京如果存在一城一策规则，则不需要合并底线规则
512					// 其余情况, 需要合并
513					if (!isBeijing || indicatorComputeRules.isEmpty()) {
514						indicatorComputeRules = mergeBaseAndCusRule(baseRules, indicatorComputeRules);
515					}
516				}
517			}
518	
519	        CategoryComputeRule res = new CategoryComputeRule();
520			if (CollectionUtils.isNotEmpty(indicatorComputeRules)) {
521				CategoryInfo categoryInfo = CategoryInfo.builder()
522						.categoryId(categoryId)
523						.categoryName(indicatorComputeRules.get(0).getCategoryName())
524						.build();
525				res.setCategoryInfoList(Collections.singletonList(categoryInfo));
526				res.setRemark(indicatorComputeRules.get(0).getRemark());
527				res.setStartTime(DateUtil.date2String(indicatorComputeRules.get(0).getStartTime()));
528				res.setDeliveryInfoList(getDeliveryInfoByRules(indicatorComputeRules));
529	
530				List<CategoryComputeRule.ComputeRule> computeRuleList = indicatorComputeRules.stream()
531						.filter(o -> IndicatorOrderServiceImpl.DEFAULT_END_TIME.equals(DateUtil.date2String(o.getEndTime())))
532						.map((rule) -> {
533							CategoryComputeRule.ComputeRule computeRule = new CategoryComputeRule.ComputeRule();
534							computeRule.setDeliveryType(rule.getDeliveryType());
535							computeRule.setHasMeasurementNode(rule.getHasMeasurementNode());
536							computeRule.setHasDeliveryNotificationNode(rule.getHasDeliveryNotificationNode());
537							if (rule.getSourceType().equals(1)) {
538								computeRule.setFuncTimeRule(JsonUtil.jsonStr2Obj(rule.getCusComputeRuleNew(), CategoryComputeRule.FuncTimeRule.class));
539							} else {
540								computeRule.setFuncTimeRule(JsonUtil.jsonStr2Obj(rule.getBaseComputeRuleNew(), CategoryComputeRule.FuncTimeRule.class));
541							}
542							return computeRule;
543						})
544						.collect(Collectors.toList());
545				res.setComputeRuleList(computeRuleList);
546			}
547	
548			// 北京的特殊处理
549			// 北京的考核规则不受底线的限制, 视为自定义属性规则, isCus始终复制为true
550			if (isBeijing && res.getComputeRuleList() != null) {
551				for (CategoryComputeRule.ComputeRule computeRule : res.getComputeRuleList()) {
552					for (TimeRule tr : computeRule.getFuncTimeRule().getTimeRuleList()) {
553						tr.setIsCus(true);
554					}
555				}
556			}
557	
558			resultDTO.success(Collections.singletonList(res));
559			return resultDTO;
560		}
