873		public ResultDTO<Void> fulfillmentTaskGenerateMaterialProcessRescaleTask(@RequestBody List<String> projectOrderIdList) {
874			if (CollectionUtils.isEmpty(projectOrderIdList)) {
875				return new ResultDTO().fail("projectOrderIdList不能为空");
876			}
877	
878			for (String projectId : projectOrderIdList) {
879				ProjectChangeParams.ChangeBaseWithOperator changeBaseWithOperator = new ProjectChangeParams.ChangeBaseWithOperator();
880				changeBaseWithOperator.setOperatorRoleList(Lists.newArrayList("super_admin"));
881				changeBaseWithOperator.setOperatorId(0L);
882				changeBaseWithOperator.setProjectOrderId(projectId);
883				try {
884					List<BudgetPreviewRpc.OrderRes> changeListDTOS = budgetPreviewRpc.listChangeApply(changeBaseWithOperator);
885					List<BudgetPreviewRpc.OrderRes> filteredChangeList = changeListDTOS.stream()
886							.filter(item -> item.getStatus() != 8000)
887							.collect(Collectors.toList());
888	
889					if (CollectionUtils.isEmpty(filteredChangeList)) {
890						continue;
891					}
892					for (BudgetPreviewRpc.OrderRes orderRes : filteredChangeList) {
893						AtomProjectChangeBO atomProjectChangeBO = new AtomProjectChangeBO();
894						atomProjectChangeBO.setProjectOrderId(projectId);
895						atomProjectChangeBO.setProjectChangeNo(orderRes.getProjectChangeNo());
896						atomProjectChangeBO.setEntityStatus(orderRes.getStatus() == 7000 ? 7000 : 2000);
897						atomProjectChangeBO.setSourceStatus(2000);
898						atomProjectChangeBO.setExtFields(Maps.newHashMap());
899						atomProjectChangeBO.setOperatorUcid(1L);
900						atomProjectChangeBO.setOperatorName("");
901	
902						ProjectOrderDto projectOrder = projectOrderManager.getByProjectOrderId(Long.valueOf(projectId));
903						// 非2.5的单子不处理
904						if (projectOrder == null || !ProjectOrderUtil.isBeiJingV2_5(projectOrder.getProcessVersion(), projectOrder.getBusinessModel())) {
905							LOGGER.info("AtomProjectChangeEventHandler not 2.5 data:{}", atomProjectChangeBO);
906						}
907						designAndDesignReviewTaskBizService.processDesignReview(atomProjectChangeBO, projectOrder);
908					}
909				} catch (RpcException e) {
910					LOGGER.warn("获取变更单失败，projectId：{}", projectId, e);
911				}
912			}
913			return new ResultDTO<>().success();
914		}
