233			ResultDTO<IndicatorOrder> resultDTO = new ResultDTO();
234			if (mixId == null || maxId == null) {
235				return new ResultDTO<>();
236			}
237			IndicatorOrderExample example = new IndicatorOrderExample().createCriteria().andIdGreaterThanOrEqualTo(mixId).andIdLessThanOrEqualTo(maxId).example();
238			List<IndicatorOrder> indicatorOrders = indicatorOrderMapper.selectByExample(example);
239	
240			List<DispatchReceiveActionTypeEnum> actionTypeEnums = new ArrayList<>(Arrays.asList(DispatchReceiveActionTypeEnum.OMS_NOTIFY_SIGN, DispatchReceiveActionTypeEnum.OMS_NOTIFY_CANCEL_MALL_SO));
241	
242			for (IndicatorOrder indicatorOrder : indicatorOrders) {
243				IndicatorOrder update = IndicatorOrder.builder().id(indicatorOrder.getId()).mtime(new Date()).build();
244				if (StringUtils.isNotBlank(indicatorOrder.getCurrentNode())) {
245					for (DispatchReceiveActionTypeEnum actionTypeEnum : DispatchReceiveActionTypeEnum.values()) {
246						if (actionTypeEnums.contains(actionTypeEnum)) {
247							continue;
248						}
249						if (actionTypeEnum.getDesc().equals(indicatorOrder.getCurrentNode())) {
250							update.setCurrentNodeCode(actionTypeEnum.getCode());
251							indicatorOrderMapper.updateByPrimaryKeySelective(update);
252							break;
253						}
254					}
255				}
256	
257			}
258			LOGGER.info("【后门执行指标订单当前节点刷新】refresh indicatorOrder mixId:{}，maxId：{}", mixId, maxId);
259			return resultDTO.success();
260		}
