336		public ResultDTO<Void> refreshIndicatorPlaceOrderTime(@RequestParam("projectOrderList") List<String> projectOrderList, @RequestParam("time") List<String> assementTimeList) {
337	
338			LOGGER.info("后台重新生成");
339			if (projectOrderList.size() != assementTimeList.size()) {
340				return new ResultDTO<>().fail("参数错误");
341			}
342			for (int i = 0; i < projectOrderList.size(); i++) {
343				String projectOrder = projectOrderList.get(i);
344				String assement = assementTimeList.get(i);
345				IndicatorOrderExample indicatorOrderExample = new IndicatorOrderExample();
346				indicatorOrderExample.createCriteria().andProjectOrderIdEqualTo(projectOrder).andCategoryIdEqualTo(
347						"029006002");
348				List<IndicatorOrder> indicatorOrders = indicatorOrderMapper.selectByExample(indicatorOrderExample);
349				if (CollectionUtil.isEmpty(indicatorOrders)) {
350					continue;
351				}
352				for (IndicatorOrder indicatorOrder : indicatorOrders) {
353					IndicatorOrderBO convert = indicatorOrderService.convert(indicatorOrder);
354					List<IndicatorEvalValBO.IndicatorEvalSDO> cusEvalResult = convert.getCusEvalResult();
355					for (IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO : cusEvalResult) {
356						if (indicatorEvalSDO.getIndicatorName().equals("下单及时")) {
357							Date parse = DateUtil.parse(assement, DateUtil.DATE_FMT_1);
358							Date endTime = DateUtil.getEndTime(parse);
359							indicatorEvalSDO.setExpectCompTime(DateUtil.formatTime(endTime));
360						}
361					}
362					IndicatorOrder update = new IndicatorOrder();
363					update.setId(convert.getId());
364					update.setCusEvalResultNew(JsonUtil.obj2JsonStr(cusEvalResult));
365					indicatorOrderDao.update(update);
366					LOGGER.info("【后门执行指标订单刷新】refresh indicatorOrder order:{}", convert.getOrderNo());
367				}
368			}
369			//如果没有结果 那么不进行更新
370			return new ResultDTO<>().success();
371		}
