479					.stream()
480					.flatMap(edge -> edge.getRuleList().stream())
481					.map(EdgeRule::getIndicatorName)
482					.findFirst()
483					.orElse(null);
484			if (!"下单及时".equals(indicatorName)) {
485				// 目前只有下单及时需要计算, 过滤一下可以减少计算量
486				return;
487			}
488			FigureRes figureRes = processCommon(ruleList, null, projectOrder, timeV2, eventNode, indicatorName, calendars);
489	
490			// 汰换任务：下单考核时间取 max(计算考核时间, 下单任务创建时间 + N自然日)，N 由 Apollo replace_supplier_assessment_buffer_days 控制
491			if (projectOrder != null && figureRes.getFigureTime() != null) {
492				String key = projectOrder.getCategoryId() + "_" + projectOrder.getDeliveryId();
