500				List<IndicatorEvalSDO> baseEvalSDOS = mergeIndicator(
501						Optional.ofNullable(JSONArray.parseArray(projectOrder.getBaseEvalResultNew(), IndicatorEvalSDO.class)).orElse(Lists.newArrayList()),
502						figureRes.getBaseEvalResult()
503				);
