505						Optional.ofNullable(JSONArray.parseArray(projectOrder.getCusEvalResultNew(), IndicatorEvalSDO.class)).orElse(Lists.newArrayList()),
506						figureRes.getCusEvalResult()
507				);
508	
509				// 清理历史数据
510				// 如果cusEvalSDOS已经重算完成, checkTime应该为false
511				// checkTime = true说明没有命中版本, 则版本信息错误, 可以清楚该指标
512				List<IndicatorEvalSDO> remove = cusEvalSDOS.stream()
513						.filter(item -> item.getIndicatorName().equals(figureRes.getIndicatorName()) && item.getCheckTime() != null && item.getCheckTime())
514						.collect(Collectors.toList());
515				if (!remove.isEmpty()) {
516					LOGGER.info("processProjectOrder清理历史数据: {}", JsonUtil.obj2JsonStr(remove));
517				}
518				cusEvalSDOS.removeIf(item -> item.getIndicatorName().equals(figureRes.getIndicatorName()) && item.getCheckTime() != null && item.getCheckTime());
519	
520				updateProjectOrder(projectOrder, baseEvalSDOS, cusEvalSDOS);
521				updateFulfillmentTask(null, projectOrder.getProjectOrderId(), projectOrder.getCategoryId(), projectOrder.getDeliveryId(), figureRes.getFigureTime(),
522						FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode(), false);
523				Optional<IndicatorEvalSDO> baseEval = baseEvalSDOS.stream()
524						.filter(item -> item.getIndicatorName().equals("下单及时"))
525						.findAny();
526				Optional<IndicatorEvalSDO> cusEval = cusEvalSDOS.stream()
527						.filter(item -> item.getIndicatorName().equals("下单及时"))
528						.findAny();
529				updateIndicatorOrder(projectOrder, baseEval, cusEval);
530			}
531		}
