591		 * 将 figureTime 中调整后的时间同步回 IndicatorEvalSDO（expectCompTime、evaluation）
592		 */
593		private void syncEvalResultWithFigureTime(IndicatorEvalSDO evalSDO, CalculatedTimeline figureTime) {
594			if (evalSDO == null) {
595				return;
596			}
597			evalSDO.setExpectCompTime(DateUtil.formatTime(figureTime.getExpectTime()));
598			if (evalSDO.getRealCompTime() != null
599					&& DateUtil.string2Date(evalSDO.getRealCompTime()).after(DateUtil.string2Date(evalSDO.getExpectCompTime()))) {
600				evalSDO.setEvaluation(1);
601			} else {
602				evalSDO.setEvaluation(0);
603			}
604		}
