122		public void createIndicatorComputeRule(List<IndicatorComputeRule> newList, String originDeliveryInfo) {
123			redoLogService.saveRedoLog(null, newList);
124	
125			Integer sourceType = newList.get(0).getSourceType();
126			Long sourceId = newList.get(0).getSourceId();
127			String categoryId = newList.get(0).getCategoryId();
128			Date startTime = newList.get(0).getStartTime();
129			Date endTime = new Date(startTime.getTime() - 1000);
130	
131			List<IndicatorComputeRule> indicatorComputeRules = bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(sourceId, sourceType, categoryId, originDeliveryInfo);
132	
133			int newVersion = 0;
134			Date oldStartTime = null;
135			Map<String, String> oldMap = new HashMap<>();
136			for (IndicatorComputeRule rule : indicatorComputeRules) {
137				oldMap.put(getDimKey(rule), sourceType.equals(0) ? rule.getBaseComputeRuleNew() : rule.getCusComputeRuleNew());
138				newVersion = Math.max(newVersion, rule.getVersion());
139				if (oldStartTime == null) {
140					oldStartTime = rule.getStartTime();
141				} else if (rule.getStartTime().compareTo(oldStartTime) > 0) {
142					oldStartTime = rule.getStartTime();
143				}
144			}
145			newVersion += 1;
146			if (oldStartTime != null && startTime.compareTo(oldStartTime) <= 0) {
147				throw new IllegalArgumentException("因存在生效时间更晚的考核版本，当前所选生效时间不可用，请调整生效时间。");
148			}
149	
150			for (IndicatorComputeRule rule : indicatorComputeRules) {
151				// 对于生效时间为正无穷的, 将end_time设置成传入的start_time - 1s
152				if (IndicatorOrderServiceImpl.DEFAULT_END_TIME.equals(DateUtil.date2String(rule.getEndTime()))) {
153					// 修改旧版本数据
154					rule.setEndTime(endTime);
155					rule.setMtime(null);
