55		public static String getRealNode(String sourceNodeCode) {
56			if (sourceNodeCode.startsWith(NODE_FIRST_PREFIX) || sourceNodeCode.startsWith(NODE_LAST_PREFIX)) {
57				return sourceNodeCode.substring(1);
58			}
59			return sourceNodeCode;
60		}
61	
62		// 根据开始时间、间隔、跳过日期类型, 日历(含日期类型), 计算结束时间
63		public static LocalDateTime figureAssessmentTime(LocalDateTime startTime, Integer interval,
64														 Integer skipBitmask, Map<LocalDateTime, Integer> calendars) {
65			if (skipBitmask == null) {
66				skipBitmask = 0;
67			}
68	
69			startTime = startTime.withHour(0).withMinute(0).withSecond(0);
70			// 如果开始日期就需要跳过，且间隔为0，则将间隔调整为1，向后顺延一天
71			if (interval.equals(0) && isSkipDate(startTime, skipBitmask, calendars)) {
72				interval = 1;
73			}
74			LocalDateTime assessmentTime = startTime;
75	
76			if (interval > 0) {
77				while (interval > 0) {
78					assessmentTime = assessmentTime.plusDays(1);
79					if (isSkipDate(assessmentTime, skipBitmask, calendars)) {
80						continue;
81					}
82					interval--;
83				}
84			} else {
85				while (interval < 0) {
86					assessmentTime = assessmentTime.plusDays(-1);
87					if (isSkipDate(assessmentTime, skipBitmask, calendars)) {
88						continue;
89					}
90					interval++;
91				}
92			}
93			return assessmentTime.withHour(23).withMinute(59).withSecond(59);
94		}
95	
96		public static Boolean isSkipDate(LocalDateTime date, Integer skipBitmask, Map<LocalDateTime, Integer> calendars) {
97			Integer dateType = calendars.getOrDefault(date, 0);
98			return (dateType & skipBitmask) > 0;
99		}
100	
101		public static Integer figureFactDays(LocalDateTime startTime, LocalDateTime endTime, Integer skipBitmask, Map<LocalDateTime, Integer> calendars) {
102			if (skipBitmask == null) {
103				skipBitmask = 0;
104			}
105			if (startTime == null || endTime == null) {
106				return null;
107			}
108			startTime = startTime.withHour(0).withMinute(0).withSecond(0);
109			endTime = endTime.withHour(23).withMinute(59).withSecond(59);
110	
111			startTime = startTime.plusDays(1);
112			int count = 0;
113			while (startTime.isBefore(endTime)) {
114				if (!isSkipDate(startTime, skipBitmask, calendars)) {
115					count++;
116				}
117				startTime = startTime.plusDays(1);
118			}
119			return count;
120		}
121	
122	}
