193		private FulfillmentTaskCreateParam buildParam(OfcDispatchNodeChangePayload payload) {
194			FulfillmentOrderDto fulfillmentOrderDto;
195			try {
196				fulfillmentOrderDto = ofcRpc.queryFulfillmentOrder(payload.getSubOrderNo());
197			} catch (Exception e) {
198				LOGGER.error("查询调度单信息失败", e);
199				return null;
200			}
201	
202			if (!StringUtils.isNumeric(fulfillmentOrderDto.getProjectOrderId())) {
203				LOGGER.info("OfcDispatchNodeChangeHandler执行终止, projectOrderId:{}不是数字", fulfillmentOrderDto.getProjectOrderId());
204				return null;
205			}
206	
207			Boolean isInScheduleConfig;
208			try {
209				isInScheduleConfig = edarStarlordRpc.queryProjectInScheduleSwitch(fulfillmentOrderDto.getProjectOrderId());
210			} catch (Exception e) {
211				throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取配置开关失败", e);
212			}
213	
214			FulfillmentTaskCreateParam fulfillmentTaskCreateParam = new FulfillmentTaskCreateParam();
215			fulfillmentTaskCreateParam.setReceiptOrderNo(payload.getDeliveryOrderNo());
216			fulfillmentTaskCreateParam.setRelateSuborderNo(payload.getSubOrderNo());
217			fulfillmentTaskCreateParam.setCategoryId(fulfillmentOrderDto.getCategoryId());
218			fulfillmentTaskCreateParam.setCategoryName(fulfillmentOrderDto.getCategoryName());
219			fulfillmentTaskCreateParam.setSupplierCode(fulfillmentOrderDto.getDeliveryId());
220			fulfillmentTaskCreateParam.setSupplierName(fulfillmentOrderDto.getDeliveryName());
221			fulfillmentTaskCreateParam.setMdmCode(fulfillmentOrderDto.getBranchCompanyCode());
222			fulfillmentTaskCreateParam.setMdmCompanyName(fulfillmentOrderDto.getBranchCompanyName());
223			fulfillmentTaskCreateParam.setProjectOrderId(fulfillmentOrderDto.getProjectOrderId());
224			fulfillmentTaskCreateParam.setHomeOrderNo(payload.getHomeOrderNo());
225			// 如果不存在正确的 任务场景 直接返回
226			if (!hasAndSetValidFulfillmentTaskType(payload, fulfillmentTaskCreateParam)) {
227				return null;
228			}
229			fulfillmentTaskCreateParam.setActiveTime(payload.getOperatorTime());
230			RoleTypeEnum roleTypeEnum = RoleTypeEnum.getByCode(payload.getRoleCode());
231			if (roleTypeEnum != null && !roleTypeEnum.getCategoryEnum().equals(RoleCategoryEnum.内部通知角色)) {
232				return null;
233			}
234			fulfillmentTaskCreateParam.setRoleType(roleTypeEnum == null ? null : roleTypeEnum.getCode());
235			fulfillmentTaskCreateParam.setTaskMode(isInScheduleConfig ? TaskModeEnum.SCHEDULE.getTaskMode() : TaskModeEnum.ORIGIN.getTaskMode());
236	
237			return fulfillmentTaskCreateParam;
238		}
