240		private Boolean hasAndSetValidFulfillmentTaskType(OfcDispatchNodeChangePayload payload,
241														  FulfillmentTaskCreateParam fulfillmentTaskCreateParam) {
242			if (DispatchProcessNodeEnum.ADDITION_COST_AUDIT.getValue().equals(payload.getNodeCode())) {
243				fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.PORTAGE_AUDIT.getTypeCode());
244				return true;
245			} else if (DispatchProcessNodeEnum.SO_SIGN_FOR.getValue().equals(payload.getNodeCode())) {
246	            try {
247					SubOrderComplexDto subOrderComplexDto = omsRpc.queryBaseByOrderNo(payload.getSubOrderNo());
248					if (!SubOrderStateEnum.WAITING_SIGN.getValue().equals(subOrderComplexDto.getStatus())) {
249						return false;
250					}
251					if (subOrderComplexDto.getSecondType().equals(SecondType.AUXILIARY.getSecondType())) {
252						fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.AUX_READY_TO_SIGN.getTypeCode());
253					} else {
254						fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode());
255						fulfillmentTaskCreateParam.setReplenishment(FlowTypeEnum.NORMAL_ORDER.getCode());
256						if (DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(subOrderComplexDto.getSecondType())) {
257							fulfillmentTaskCreateParam.setReplenishment(FlowTypeEnum.REVERSE_ORDER.getCode());
258						}
259					}
260	            } catch (RpcException e) {
261					LOGGER.error("查询订单信息失败orderNo:{}",payload.getSubOrderNo(), e);
262	            	return false;
263	            }
264				return true;
265			} else if(DispatchProcessNodeEnum.CHECK_NODE.getValue().equals(payload.getNodeCode())) {
266				if (payload.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.INSTALL.getValue())) {
267					fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.INSTALL_READY_TO_SIGN.getTypeCode());
268					return true;
269				} else if (payload.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.EMBEDDED_PARTS_INSTALL.getValue())) {
270					fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.PRE_INSTALL_READY_TO_SIGN.getTypeCode());
271					return true;
272				} else if (payload.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.MEASURE.getValue())) {
273					fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.MEASURE_ACCEPTANCE.getTypeCode());
274					return true;
275				} else if (payload.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.RECHECK_SCALE.getValue())) {
276					fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.RECHECK_ACCEPTANCE.getTypeCode());
277					return true;
278				} else if (payload.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DESIGN.getValue())) {
279					fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.DESIGN_READY_TO_SIGN.getTypeCode());
280					return true;
281				}
282			}
283			return false;
284		}
