28	 * @date 2020/2/21 12:04
29	 */
30	@Component
31	@Slf4j
32	public class OperatorInterceptor implements HandlerInterceptor {
33	
34		public static final String X_KE_USER_NAME = "X-KE-USER-NAME";
35	
36		public static final String X_KE_SELECT_ROLE = "X-KE-SELECT-ROLE";
37	
38		@Override
39		public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler)
40			throws Exception {
41			String header = request.getHeader(Operator.UC_ID);
42			String role = request.getHeader(X_KE_SELECT_ROLE);
43			if (StringUtils.isNotBlank(header)) {
44				String username = "";
45				if (StringUtils.isNotBlank(request.getHeader(Operator.USERNAME))) {
46					username = URLDecoder.decode(request.getHeader(Operator.USERNAME), "utf-8");
47				}
48				if(StringUtils.isBlank(username)) {
49					username = request.getHeader(X_KE_USER_NAME);
50					if(StringUtils.isNotBlank(username)) {
51						username = URLDecoder.decode(username, "utf-8");
52					}
53				}
54				Integer gbCode = null;
55				if(StringUtils.isNotBlank(request.getHeader(Operator.X_KE_GB_CODE))){
56					try {
57						gbCode = Integer.parseInt(request.getHeader(Operator.X_KE_GB_CODE));
58					}catch (Exception ex){
59						LOGGER.info("error = {}",ex);
60					}
61				}
62				if(StringUtils.isEmpty(username)) {
63					username = buildUsername(request.getHeader(Operator.X_KE_EP_NAME));
64				}
65				Operator operator = Operator.builder().ucid(Long.valueOf(header)).account(request.getHeader(Operator.ACCOUNT)).username(username).gbCode(gbCode).build();
66				if(StringUtils.isNotBlank(role)) {
67					operator.setRole(RoleEnum.getRoleByName(role));
68					operator.setHasRoles(Lists.newArrayList(role));
69				}
70				//Operator operator = new Operator(Long.valueOf(header), request.getHeader(Operator.ACCOUNT), username);
71				OperatorContextHandler.getContext().setOperator(operator);
72			} else {
73				String ucid = request.getHeader(Operator.X_KE_UCID);
74				if (StringUtils.isBlank(ucid)) {
75					OperatorContextHandler.getContext().setOperator(new Operator());
76					return true;
77				}
78				Operator operator = new Operator();
79				operator.setSystemCode(request.getHeader(Operator.X_KE_EP_ID));
80				String name = buildUsername(request.getHeader(Operator.X_KE_EP_NAME));
81				if(StringUtils.isBlank(name)) {
82					name = buildUsername(request.getHeader(X_KE_USER_NAME));
83				}
84				operator.setUsername(name);
85				operator.setGbCode(buildGbCode(request.getHeader(Operator.X_KE_GB_CODE)));
86				operator.setUcid(Long.parseLong(ucid));
87				operator.setMobile(buildMobile(request.getHeader(Operator.X_KE_MOBILE)));
88				if(StringUtils.isNotBlank(role)) {
89					operator.setRole(RoleEnum.getRoleByName(role));
90					operator.setHasRoles(Lists.newArrayList(role));
91				}
92				OperatorContextHandler.getContext().setOperator(operator);
93				LOGGER.info("从请求头中获取到的ucId:{},source:{},mobile{}",ucid,request.getHeader("projectSource"),request.getHeader(Operator.X_KE_MOBILE));
94				LOGGER.info("operator信息:{}", JSONObject.toJSONString(operator));
95			}
96			LOGGER.info("operator = {}", OperatorContextHandler.getContext().getOperator());
97			return true;
98		}
99	
100		@Override
101		public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler,
102									@Nullable Exception ex) throws Exception {
103			OperatorContextHandler.clearContext();
104		}
105		private String buildMobile(String mobile) throws UnsupportedEncodingException {
106			if (StringUtils.isBlank(mobile)) {
107				return "";
108			}
109			return URLDecoder.decode(mobile, "utf-8");
110		}
111	
112		private String buildUsername(String username) throws UnsupportedEncodingException {
113			if (StringUtils.isBlank(username)) {
114				return "";
115			}
116			return URLDecoder.decode(username, "utf-8");
117		}
118	
119		private Integer buildGbCode(String gbCode) {
120			if (StringUtils.isBlank(gbCode)) {
121				return null;
122			}
123			return Integer.valueOf(gbCode);
124		}
125	}
